import { Link, useLocation, useNavigate } from "react-router-dom";
import { useState } from "react";
import { API } from "../api/api";

export default function Navbar() {
  const location = useLocation();
  const nav = useNavigate();
  const [openProfile, setOpenProfile] = useState(false);
  const [user, setUser] = useState(null);

  const fetchUser = async () => {
    try {
      const res = await API.get("/auth/verify");
      setUser(res.data.user);
      setOpenProfile(true);
    } catch {
      alert("Not logged in");
    }
  };

  return (
    <>
      {/* NAVBAR */}
      <nav style={styles.navbar}>
        <h2 style={styles.logo} onClick={() => nav("/home")}>
          PollHub 🚀
        </h2>

        <div style={styles.links}>
          <Link to="/home" style={styles.link}>
            <span style={location.pathname === "/home" ? styles.active : null}>
              Home
            </span>
          </Link>

          <Link to="/polls" style={styles.link}>
            <span style={location.pathname === "/polls" ? styles.active : null}>
              Polls
            </span>
          </Link>

          <Link to="/surveys" style={styles.link}>
            <span style={location.pathname === "/surveys" ? styles.active : null}>
              Surveys
            </span>
          </Link>
        </div>

        <div style={{ display: "flex", gap: "10px" }}>
          <button style={styles.profile} onClick={fetchUser}>
            👤
          </button>

          <button
            style={styles.logout}
            onClick={async () => {
              await API.post("/auth/logout");
              nav("/");
            }}
          >
            Logout
          </button>
        </div>
      </nav>

      {/* PROFILE DRAWER */}
      {openProfile && (
        <div style={styles.overlay} onClick={() => setOpenProfile(false)}>
          <div style={styles.drawer} onClick={(e) => e.stopPropagation()}>
            <h2>👤 Profile</h2>

            {user && (
              <>
                <p><b>Name:</b> {user.name}</p>
                <p><b>Email:</b> {user.email}</p>

                <textarea
                  placeholder="Write bio..."
                  style={styles.textarea}
                />

                <input type="file" />

                <button style={styles.saveBtn}>
                  Save Profile
                </button>
              </>
            )}
          </div>
        </div>
      )}
    </>
  );
}
